import base64
import json
import os
import subprocess
import sys
import time
import zipfile
from pathlib import Path

# ── Embedded files (base64) ──────────────────────────────────────────────────
_FILES = {
    'src/models/__init__.py': '',
    'src/models/deeplob.py': '',
    'src/models/tcn.py': '',
    'src/models/lob_transformer.py': '',
    'src/models/cnn_lstm_attention.py': '',
    'src/models/neural_cde.py': '',
    'src/models/rac_moe.py': '',
    'anchored_runner.py': ''
}


def extract_files(base_dir: str) -> None:
    for rel, b64 in _FILES.items():
        p = Path(base_dir) / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"  extracted {rel}")


# ── Paths ────────────────────────────────────────────────────────────────────
WORKING = Path("/kaggle/working")
RUNS_DIR = WORKING / "runs"
CODE_DIR = WORKING / "code"
CACHE_DIR = WORKING / "fi2010_npy_cache"
RUNS_DIR.mkdir(parents=True, exist_ok=True)
CACHE_DIR.mkdir(parents=True, exist_ok=True)

# ── Reinstall torch if GPU arch is unsupported (P100 = sm_60) ────────────────
import torch
cap = torch.cuda.get_device_capability() if torch.cuda.is_available() else (0, 0)
sm = cap[0] * 10 + cap[1]
if sm > 0:
    supported = {int(a.replace("sm_", "")) for a in torch.cuda.get_arch_list()}
    if sm not in supported:
        print(f"arch unsupported (sm_{sm}) -> reinstalling cu121 torch ...")
        subprocess.check_call([
            sys.executable, "-m", "pip", "install", "-q",
            "torch==2.5.1+cu121", "torchvision==0.20.1+cu121",
            "--extra-index-url", "https://download.pytorch.org/whl/cu121",
        ])
        print("cu121 torch installed")

# ── Extract embedded files ───────────────────────────────────────────────────
print("Extracting embedded files...")
extract_files(str(CODE_DIR))
RUNNER = CODE_DIR / "anchored_runner.py"
assert RUNNER.exists(), f"Runner not extracted: {RUNNER}"
print("Extraction OK")

env = os.environ.copy()
pp = env.get("PYTHONPATH", "")
env["PYTHONPATH"] = f"{CODE_DIR}:{pp}" if pp else str(CODE_DIR)

# ── FI-2010 data path ────────────────────────────────────────────────────────
FI2010 = None
for _r in [
    "/kaggle/input/datasets/wzy841127938/fi2010",
    "/kaggle/input/fi2010",
    "/kaggle/input/fi-2010",
    "/kaggle/input/fi-2010/BenchmarkDatasets/NoAuction/1.NoAuction_Zscore",
]:
    if Path(_r).exists():
        FI2010 = Path(_r)
        break
if FI2010 is None:
    import glob as _glob
    found = _glob.glob("/kaggle/input/**/NoAuction_Zscore_Training", recursive=True)
    if found:
        FI2010 = Path(found[0]).parent
assert FI2010 is not None, "FI-2010 not found"
print(f"FI-2010 OK at {FI2010}")


# ── Campaign definition (fold=9 only, seeds 0,1,2, save best.pt) ─────────────
MODEL = "lob_transformer"
FOLDS = [9]
SEEDS = [0, 1, 2]
EPOCHS = 80
WALL_CLOCK_LIMIT = 11.0 * 3600
t_start = time.time()


def run_job(model: str, fold: int, seed: int, smoke: bool = False) -> str:
    run_id = f"anchored_references__{model}__f{fold}__k10__s{seed}__none"
    summary = RUNS_DIR / run_id / "summary.json"
    if summary.exists():
        try:
            if json.loads(summary.read_text()).get("state") == "completed":
                print(f"SKIP {run_id}")
                return "skipped"
        except Exception:
            pass
    print(f"\nRUN: {run_id}  smoke={smoke}")
    cmd = [
        sys.executable, str(RUNNER),
        "--model", model,
        "--fold", str(fold),
        "--seed", str(seed),
        "--data-root", str(FI2010),
        "--out-dir", str(RUNS_DIR),
        "--epochs", "3" if smoke else str(EPOCHS),
    ]
    if smoke:
        cmd.append("--smoke")
    t0 = time.time()
    try:
        rc = subprocess.run(cmd, env=env).returncode
    except Exception as exc:
        print(f"  EXCEPTION launching job: {exc}")
        return "failed"
    elapsed = time.time() - t0
    stat = "completed" if rc == 0 else "failed"
    print(f"  -> {stat} ({elapsed:.0f}s)")
    return stat


# ── Smoke test ───────────────────────────────────────────────────────────────
print("\n" + "=" * 60)
print(f"SMOKE: {MODEL} fold=9 seed=0 epochs=3")
smoke_result = run_job(MODEL, fold=9, seed=0, smoke=True)
smoke_dir = RUNS_DIR / f"anchored_references__{MODEL}__f9__k10__s0__none"
if smoke_result not in ("completed", "skipped"):
    print(f"SMOKE FAILED (status={smoke_result}). Aborting kernel.")
    sys.exit(1)
smoke_summary = json.loads((smoke_dir / "summary.json").read_text())
print("Smoke metrics (test):", json.dumps(smoke_summary["test"], indent=2))
print(f"Data: train={smoke_summary['data']['train_samples']:,}")
print("SMOKE PASSED")

# ── Full run: fold=9, seeds 0,1,2 ─────────────────────────────────────────────
print("\n" + "=" * 60)
print(f"LOBT F9: model={MODEL} fold=9 seeds={SEEDS}")
job_results = {}
for seed in SEEDS:
    if time.time() - t_start > WALL_CLOCK_LIMIT:
        print(f"WALL_CLOCK_LIMIT reached; stopping before seed={seed}")
        break
    key = f"{MODEL}_f9_s{seed}"
    try:
        job_results[key] = run_job(MODEL, fold=9, seed=seed)
    except Exception as exc:
        print(f"  UNCAUGHT EXCEPTION: {exc}")
        job_results[key] = "error"

print("\nJob results:", json.dumps(job_results, indent=2))

# ── Package: include best.pt along with logits ────────────────────────────────
print("\nPackaging completed runs (including best.pt)...")
zip_path = WORKING / "anchored_lobt_f9_checkpoint.zip"
packed = 0
with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED, compresslevel=1) as zf:
    for d in sorted(RUNS_DIR.iterdir()):
        if not d.is_dir():
            continue
        if f"__{MODEL}__f9__" not in d.name:
            continue
        sumpath = d / "summary.json"
        if not sumpath.exists():
            continue
        try:
            s = json.loads(sumpath.read_text())
            if s.get("state") != "completed":
                continue
        except Exception:
            continue
        # Pack all run artifacts including best.pt
        for fname in ["summary.json", "test_logits.pt", "validation_logits.pt", "best.pt"]:
            fp = d / fname
            if fp.exists():
                zf.write(fp, f"{d.name}/{fname}")
                print(f"  added {d.name}/{fname} ({fp.stat().st_size/1e6:.1f} MB)")
        packed += 1
sz = zip_path.stat().st_size / 1e6 if zip_path.exists() else 0
print(f"ZIP: {zip_path} ({sz:.1f} MB) — {packed} completed runs")
print(f"\nLOBT_F9_CHECKPOINT_DONE")
